import sys

def min_front_kicks(h, w, grid, start_row, start_col, end_row, end_col):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = [(start_row, start_col, 0)]  # (row, col, number of front kicks)
    visited = set()

    while queue:
        row, col, front_kicks = queue.pop(0)

        if (row, col) == (end_row, end_col):
            return front_kicks

        if (row, col) in visited:
            continue

        visited.add((row, col))

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc

            if 0 <= new_row < h and 0 <= new_col < w and grid[new_row][new_col] == '.':
                queue.append((new_row, new_col, front_kicks))

            elif 0 <= new_row < h and 0 <= new_col < w and grid[new_row][new_col] == '#':
                if 0 <= new_row - 2 >= 0 and 0 <= new_col - 2 >= 0 and grid[new_row - 2][new_col - 2] == '.':
                    grid[new_row - 2][new_col - 2] = '.'
                    queue.append((new_row - 2, new_col - 2, front_kicks + 1))

                if 0 <= new_row - 2 >= 0 and 0 <= new_col + 2 < w and grid[new_row - 2][new_col + 2] == '.':
                    grid[new_row - 2][new_col + 2] = '.'
                    queue.append((new_row - 2, new_col + 2, front_kicks + 1))

                if 0 <= new_row + 2 < h and 0 <= new_col - 2 >= 0 and grid[new_row + 2][new_col - 2] == '.':
                    grid[new_row + 2][new_col - 2] = '.'
                    queue.append((new_row + 2, new_col - 2, front_kicks + 1))

                if 0 <= new_row + 2 < h and 0 <= new_col + 2 < w and grid[new_row + 2][new_col + 2] == '.':
                    grid[new_row + 2][new_col + 2] = '.'
                    queue.append((new_row + 2, new_col + 2, front_kicks + 1))

if __name__ == "__main__":
    input_data = sys.stdin.read().split('\n')
    h, w = map(int, input_data[0].split())
