    print(result)

from typing import List

def min_front_kicks(H: int, W: int, S: List[str], A: int, B: int, C: int, D: int) -> int:
    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W and S[x][y] == '.'

    def bfs(start_x, start_y):
        queue = [(start_x, start_y)]
        visited = set()
        visited.add((start_x, start_y))
        front_kick_count = 0

        while queue:
            new_queue = []

            for x, y in queue:
                if (x, y) == (C, D):
                    return front_kick_count

                for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx, ny = x + dx, y + dy
                    if is_valid(nx, ny) and (nx, ny) not in visited:
                        new_queue.append((nx, ny))
                        visited.add((nx, ny))
                        front_kick_count += 1

            queue = new_queue

        return -1

    return bfs(A, B)

